//go:build darwin

package main

// Watches the Mac clipboard so copied text can be pasted on connected phones.
// Uses NSPasteboard's changeCount through the Objective-C runtime (purego, no
// cgo): one cheap call every half second, nothing else while nothing changes.

import (
	"os/exec"
	"runtime"
	"time"

	"github.com/ebitengine/purego"
	"github.com/ebitengine/purego/objc"
)

// Clipboard types password managers use to mark secrets (nspasteboard.org).
var privateTypes = []string{
	"org.nspasteboard.ConcealedType",
	"org.nspasteboard.TransientType",
	"org.nspasteboard.AutoGeneratedType",
	"com.agilebits.onepassword",
}

func watchClipboard(s *Server) {
	defer func() {
		if v := recover(); v != nil {
			logf("clipboard watcher stopped: %v; falling back to pbpaste", v)
			go pollPbpaste(s)
		}
	}()
	if _, err := purego.Dlopen("/System/Library/Frameworks/AppKit.framework/AppKit", purego.RTLD_GLOBAL|purego.RTLD_LAZY); err != nil {
		logf("clipboard: %v; falling back to pbpaste", err)
		go pollPbpaste(s)
		return
	}
	libobjc, err := purego.Dlopen("/usr/lib/libobjc.A.dylib", purego.RTLD_GLOBAL|purego.RTLD_LAZY)
	if err != nil {
		go pollPbpaste(s)
		return
	}
	var poolPush func() uintptr
	var poolPop func(uintptr)
	purego.RegisterLibFunc(&poolPush, libobjc, "objc_autoreleasePoolPush")
	purego.RegisterLibFunc(&poolPop, libobjc, "objc_autoreleasePoolPop")

	runtime.LockOSThread()
	var (
		selGeneral  = objc.RegisterName("generalPasteboard")
		selChange   = objc.RegisterName("changeCount")
		selTypes    = objc.RegisterName("types")
		selContains = objc.RegisterName("containsObject:")
		selString   = objc.RegisterName("stringForType:")
		selUTF8     = objc.RegisterName("UTF8String")
		selAlloc    = objc.RegisterName("alloc")
		selInitUTF8 = objc.RegisterName("initWithUTF8String:")
	)
	nsString := func(v string) objc.ID { // owned (+1), kept for the life of the process
		return objc.ID(objc.GetClass("NSString")).Send(selAlloc).Send(selInitUTF8, v)
	}
	plain := nsString("public.utf8-plain-text")
	var private []objc.ID
	for _, t := range privateTypes {
		private = append(private, nsString(t))
	}

	pool := poolPush()
	pb := objc.ID(objc.GetClass("NSPasteboard")).Send(selGeneral)
	last := objc.Send[int](pb, selChange)
	poolPop(pool)
	logf("clipboard watcher running")

	for range time.Tick(500 * time.Millisecond) {
		pool := poolPush()
		if c := objc.Send[int](pb, selChange); c != last {
			last = c
			if len(s.Phones()) > 0 && s.cfg.Get().ShareClipboard {
				secret := false
				if types := pb.Send(selTypes); types != 0 {
					for _, t := range private {
						if objc.Send[bool](types, selContains, t) {
							secret = true
							break
						}
					}
				}
				if !secret {
					if str := pb.Send(selString, plain); str != 0 {
						s.ClipboardChanged(objc.Send[string](str, selUTF8))
					}
				}
			}
		}
		poolPop(pool)
	}
}

// pollPbpaste is the fallback: only runs pbpaste while a phone is connected.
func pollPbpaste(s *Server) {
	last := ""
	if out, err := exec.Command("/usr/bin/pbpaste", "-Prefer", "txt").Output(); err == nil {
		last = string(out)
	}
	for range time.Tick(1500 * time.Millisecond) {
		if len(s.Phones()) == 0 || !s.cfg.Get().ShareClipboard {
			continue
		}
		out, err := exec.Command("/usr/bin/pbpaste", "-Prefer", "txt").Output()
		if err != nil {
			continue
		}
		if text := string(out); text != last {
			last = text
			s.ClipboardChanged(text)
		}
	}
}
